ndary-container）；chip / 分段按钮 / 菜单 / snackbar 按 M3 规格。 */\n\n:root:not([data-style=\"glass\"]) .section {\n  padding: 0;\n  border: 0;\n  background: none;\n  box-shadow: none;\n  -webkit-backdrop-filter: none;\n  backdrop-filter: none;\n  animation-duration: var(--md-sys-motion-spring-default-spatial-duration);\n  animation-timing-function: var(--md-sys-motion-spring-default-spatial);\n}\n\n/* 常驻卡片靠色调分层、不投影（M3E 的阴影只留给菜单 / snackbar 这类浮层）。 */\n:root:not([data-style=\"glass\"]) :where(.connection, .advanced, .custom-theme-editor, .hp-connection, .hp-update, .hp-queue, .panel-header, .subs-item, .subtitle-row.is-current) {\n  box-shadow: none;\n}\n\n:root:not([data-style=\"glass\"]) .section-heading { padding: 6px 6px 14px; }\n\n:root:not([data-style=\"glass\"]) .section-icon {\n  border-radius: var(--md-sys-shape-corner-large);\n  color: var(--md-sys-color-on-primary);\n  background: var(--md-sys-color-primary);\n}\n\n:root:not([data-style=\"glass\"]) .subtitle-preview { margin-bottom: 10px; border-radius: var(--fushi-shape-card); }\n\n/* ── ① 分段列表 ── */\n:root:not([data-style=\"glass\"]) :is(.setting-list, .hp-group) {\n  gap: 2px;\n}\n\n:root:not([data-style=\"glass\"]) .hp-group {\n  overflow: visible;\n  border: 0;\n  background: none;\n  box-shadow: none;\n}\n\n:root:not([data-style=\"glass\"]) :is(.setting-list > .setting-row, .hp-group > .hp-toggle) {\n  padding: 12px 20px;\n  border: 0;\n  border-radius: var(--fushi-shape-segment);\n  background-color: var(--md-sys-color-surface-container-lowest);\n}\n\n:root:not([data-style=\"glass\"]) .hp-group > .hp-toggle { padding: 10px 16px; }\n\n:root:not([data-style=\"glass\"]) :is(.setting-list > :first-child, .hp-group > :first-child) {\n  border-top-left-radius: var(--md-sys-shape-corner-large-increased);\n  border-top-right-radius: var(--md-sys-shape-corner-large-increased);\n}\n\n:root:not([data-style=\"glass\"]) :is(.setting-list > :last-child, .hp-group > :last-child) {\n  border-bottom-left-radius: var(--md-sys-