ctive::-moz-range-thumb { width: 2px; }\n\n:root:not([data-style=\"glass\"]) input[type=\"range\"]:focus-visible {\n  outline: 3px solid color-mix(in oklch, var(--md-sys-color-primary) 54%, transparent);\n  outline-offset: 2px;\n  border-radius: var(--md-sys-shape-corner-small);\n}\n\n:root:not([data-style=\"glass\"]) input[type=\"range\"]:disabled {\n  opacity: var(--md-sys-state-disabled-content-opacity);\n  cursor: default;\n}\n\n/* ── 输入框：surface-container-highest 实色填充、无内阴影；焦点是 2px 主色内描边。 ── */\n:root:not([data-style=\"glass\"]) :where(\n  input:not([type]), input[type=\"text\"], input[type=\"search\"], input[type=\"number\"],\n  input[type=\"password\"], input[type=\"url\"], input[type=\"email\"], input[type=\"tel\"], textarea\n) {\n  padding: 0 16px;\n  background-color: var(--md-sys-color-surface-container-highest);\n  box-shadow: none;\n  color: var(--md-sys-color-on-surface);\n}\n\n:root:not([data-style=\"glass\"]) :where(\n  input:not([type]), input[type=\"text\"], input[type=\"search\"], input[type=\"number\"],\n  input[type=\"password\"], input[type=\"url\"], input[type=\"email\"], input[type=\"tel\"], textarea\n):focus {\n  border-color: transparent;\n  background-color: var(--md-sys-color-surface-container-highest);\n  box-shadow: inset 0 0 0 2px var(--md-sys-color-primary);\n}\n\n:root:not([data-style=\"glass\"]) textarea {\n  padding: 10px 16px;\n  border-radius: var(--md-sys-shape-corner-large);\n}\n\n:root:not([data-style=\"glass\"]) .token-field button {\n  border-left-color: transparent;\n  color: var(--md-sys-color-primary);\n  font-size: var(--md-sys-typescale-label-large-size);\n  font-weight: var(--md-sys-typescale-weight-emphasized);\n}\n\n/* ── 下拉（glass-select）：触发器与输入框同形（实色填充、focus 2px 主色内描边），菜单是 M3 menu：\n   surface-container、level 2 投影、corner-large；选中行 secondary-container + check。展开时\n   从顶缘弹出（@starting-style，弹簧）。 ── */\n:root:not([data-style=\"glass\"]) .fgs-trigger {\n  padding: 0 8px 0 16px;\n  border-color: transparent;\n  background-