ption.is-selected.is-active {\n  background-color: color-mix(in oklch, var(--md-sys-color-on-secondary-container) var(--md-sys-state-hover-opacity), var(--md-sys-color-secondary-container));\n}\n\n:root:not([data-style=\"glass\"]) .fgs-check { color: var(--md-sys-color-on-secondary-container); }\n\n/* ── snackbar（设置页 .save-toast / 侧边栏 .toast；页内 #fushi-toast 同值）：inverse-surface 底、\n   --fushi-shape-snackbar（= app kFushiM3eInverseSurfaceRadius 24）、level 3 投影。 ── */\n:root:not([data-style=\"glass\"]) :is(.save-toast, .toast) {\n  color: var(--md-sys-color-inverse-on-surface);\n  background-color: var(--md-sys-color-inverse-surface);\n  border-color: transparent;\n  border-radius: var(--fushi-shape-snackbar);\n  box-shadow: var(--md-sys-elevation-level3);\n  -webkit-backdrop-filter: none;\n  backdrop-filter: none;\n}\n\n/* ══ 通用组件库（扩展页面与 fushi_server WebUI 共用）══\n   上面各段是扩展三页长出来的控件形态；这一段把「结构」也收进共享层，并补齐扩展页暂时没用到、\n   WebUI 要用的组件。WebUI 经 scripts/sync-mirrors.mjs 生成的 web_kit.g.dart 原样加载本文件。\n   约定：\n   · 扩展页已有同名 class 的组件（设置行 / 按钮 / 图标按钮），这里的结构规则包在 :where() 里、\n     特异性为 0——扩展页面 CSS 的同名规则照旧压过它，扩展外观不变；页面没写的（WebUI）就用这里的。\n   · 新组件只用 token（--md-sys-* / --fushi-shape-* / --fushi-mat-*），两套风格自动跟随：M3E 下\n     --fushi-mat-* 是实色 / 无描边 / 无模糊，液态玻璃下是半透明 + 模糊 + 高光。\n   · 选中态一律 secondary-container + on-secondary-container，悬停 / 按下叠 on- 色状态层，\n     形状按压形变走 --fushi-ease-spatial 弹簧。 */\n\n/* ── 排版辅助 ── */\n:where(:root) :where(.kit-title-large) {\n  margin: 0;\n  font-size: var(--md-sys-typescale-title-large-size);\n  line-height: var(--md-sys-typescale-title-large-line-height);\n  font-weight: var(--md-sys-typescale-weight-regular);\n}\n\n:where(:root) :where(.kit-title-medium) {\n  margin: 0;\n  font-size: var(--md-sys-typescale-title-medium-size);\n  line-height: var(--md-sys-typescale-title-medium-line-height);\n  font-weight: var(--md-sys-typescale-weight-medium);\n}\n\n:where(:root) :where(.kit-supporting) {\n  margin: 4px 0 0;\n  color: var(--md-sys-color-on-surface-variant);\n  font-