s-motion-spring-default-spatial),\n    visibility 0s linear var(--md-sys-motion-spring-default-spatial-duration);\n}\n:where(:root) :where(.nav-rail.is-drawer.is-open) {\n  visibility: visible;\n  transform: none;\n  transition: transform var(--md-sys-motion-spring-default-spatial-duration) var(--md-sys-motion-spring-default-spatial);\n}\n:where(:root) :where(.nav-scrim) {\n  position: fixed;\n  z-index: 29;\n  inset: 0;\n  background: color-mix(in oklch, var(--md-sys-color-scrim) 32%, transparent);\n  opacity: 0;\n  pointer-events: none;\n  transition: opacity var(--fushi-dur-medium) var(--fushi-ease);\n}\n:where(:root) :where(.nav-scrim.is-open) {\n  opacity: 1;\n  pointer-events: auto;\n}\n\n/* ── 滚动条：下拉 / 菜单弹层与独立网页（WebUI）用细的圆角滑块，无箭头按钮，轨道透明。\n   Chromium / WebKit 走 ::-webkit-scrollbar（同时设了标准属性它会被忽略，所以标准属性只给不认它的 Firefox）。 ── */\n:where(:root) :where(.fgs-menu, .kit-menu)::-webkit-scrollbar,\n:where(:root[data-fushi-theme-host=\"page\"]) ::-webkit-scrollbar { width: 12px; height: 12px; }\n:where(:root) :where(.fgs-menu, .kit-menu)::-webkit-scrollbar-button,\n:where(:root[data-fushi-theme-host=\"page\"]) ::-webkit-scrollbar-button { display: none; }\n:where(:root) :where(.fgs-menu, .kit-menu)::-webkit-scrollbar-track,\n:where(:root[data-fushi-theme-host=\"page\"]) ::-webkit-scrollbar-track,\n:where(:root) :where(.fgs-menu, .kit-menu)::-webkit-scrollbar-corner,\n:where(:root[data-fushi-theme-host=\"page\"]) ::-webkit-scrollbar-corner { background: transparent; }\n:where(:root) :where(.fgs-menu, .kit-menu)::-webkit-scrollbar-thumb,\n:where(:root[data-fushi-theme-host=\"page\"]) ::-webkit-scrollbar-thumb {\n  border: 4px solid transparent;\n  border-radius: var(--md-sys-shape-corner-full);\n  background: color-mix(in oklch, var(--md-sys-color-on-surface) 28%, transparent) padding-box;\n}\n:where(:root) :where(.fgs-menu, .kit-menu)::-webkit-scrollbar-thumb:hover,\n:where(:root[data-fushi-theme-host=\"page\"]) ::-webkit-scrollbar-thumb:hover {\n  background-color: color-mix(in oklch, var(--md-sys-color-on-surface) 45%, transparent);\n}\n@supports not selector(::-webkit-scrollbar) {\n  :where(:root) :where(.fgs-menu, .kit-menu),\n  :where(:root[data-fushi-theme-host=\"page\"]) :where(*) {\n    scrollbar-width: thin;\n    scrollbar-color: color-mix(in oklch, var(--md-sys-color-on-surface) 28%, transparent) transparent;\n  }\n}\n\n/* ── 统计块：一块色调面上的「标签 + 大数字 + 说明」。 ── */\n:where(:root) :where(.stat-tile) {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  min-width: 0;\n  padding: 16px 20px;\n  border: 1px solid var(--fushi-mat-edge);\n  border-radius: var(--md-sys-shape-corner-large-increased);\n  background-color: var(--fushi-mat-fill);\n}\n\n:root:not([data-style=\"glass\"]) :where(.stat-tile) { background-color: var(--md-sys-color-surface-container-low); }\n\n:where(:root) :where(.stat-tile.is-primary) {\n  border-color: transparent;\n  color: var(--md-sys-color-on-primary-container);\n  background-color: var(--md-sys-color-primary-container);\n}\n\n:where(:root) :where(.stat-label) {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  color: var(--md-sys-color-on-surface-variant);\n  font-size: var(--md-sys-typescale-label-large-size);\n  font-weight: var(--md-sys-typescale-weight-medium);\n}\n\n:where(:root) :where(.stat-tile.is-primary .stat-label, .stat-tile.is-primary .stat-sub) { color: inherit; }\n\n:where(:root) :where(.stat-label) > :where(svg.msr, .msr-slot) {\n  width: 18px;\n  height: 18px;\n}\n\n:where(:root) :where(.stat-value) {\n  font-size: var(--md-sys-typescale-display-small-size);\n  line-height: var(--md-sys-typescale-display-small-line-height);\n  font-variant-numeric: tabular-nums;\n  overflow-wrap: anywhere;\n}\n\n:where(:root) :where(.stat-sub) {\n  color: var(--md-sys-color-on-surface-variant);\n  font-size: var(--md-sys-typescale-body-small-size);\n}\n\n/* ── 键值网格（运行状态 / 引擎信息）：标签 label-medium + 值 body-medium。 ── */\n:where(:root) :where(.kv-grid) {\n  display: grid;\n  grid-template-colum